class Solution {
    public boolean canCross(int[] stones) {
        java.util.Map<Integer, java.util.Set<Integer>> map = new java.util.HashMap<>();
        for (int s : stones) map.put(s, new java.util.HashSet<>());
        map.get(0).add(0);
        for (int s : stones) {
            for (int k : map.get(s)) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step > 0 && map.containsKey(s + step)) {
                        map.get(s + step).add(step);
                    }
                }
            }
        }
        return !map.get(stones[stones.length - 1]).isEmpty();
    }
}

import java.util.*;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        Map<Integer, Integer> posToIdx = new HashMap<>();
        for (int i = 0; i < n; i++) posToIdx.put(stones[i], i);
        boolean[][] dp = new boolean[n][n + 1];
        dp[0][0] = true;
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= i; k++) {
                if (!dp[i][k]) continue;
                for (int jump = k - 1; jump <= k + 1; jump++) {
                    if (jump <= 0) continue;
                    int nextPos = stones[i] + jump;
                    if (posToIdx.containsKey(nextPos)) {
                        int nextIdx = posToIdx.get(nextPos);
                        if (jump < dp[0].length) {
                            dp[nextIdx][jump] = true;
                        }
                    }
                }
            }
        }
        for (int k = 0; k <= n; k++) {
            if (dp[n - 1][k]) return true;
        }
        return false;
    }
}
